// Single source of truth for branding in the app: names, colours and the BIZOMAT platform links.
// Logo geometry and brand colours come from bizomat-brand.ts, generated by shared/brand/build.mjs (never edit it by hand).
import { BRAND_COLORS } from './bizomat-brand';
import { DEFAULT_COLOR, PRODUCT } from '../../shared/brand';

export const BRAND = {
  /** The platform this product belongs to. Never followed by a trade mark sign. */
  platform: PRODUCT.platform,
  platformTagline: 'Intelligent Business Automation Platform',
  statement: 'Automate work. Connect systems. Get business done.',
  /** Short product name, used next to the BIZOMAT wordmark. */
  product: PRODUCT.name,
  /** Full product name: page titles, metadata, screen readers. */
  full: PRODUCT.full,
  description: 'Projects, tasks and teams in one shared workspace.',
  colors: BRAND_COLORS,
  /** Colour for new workspaces and folders. */
  defaultColor: DEFAULT_COLOR,
  /** Browser UI colour (meta theme-color): the top bar's surface in each theme. */
  themeColor: { light: '#ffffff', dark: '#101a28' },
  /** Where privacy requests go: BIZOMAT's contact address (as on the website). */
  privacyContact: 'info@bizomat.ai',
  privacyUpdated: '6 November 2026',
} as const;

/**
 * BIZOMAT platform addresses. Change them here only. They open in the same tab; links to other hosts carry
 * rel="noopener" (see platformLinkProps).
 */
export const PLATFORM_URLS = {
  website: 'https://bizomat.ai/',
  productPage: 'https://bizomat.ai/work/',
  cad: 'https://bizomat.ai/cad/',
  resources: 'https://bizomat.ai/resources/',
  privacy: 'https://bizomat.ai/privacy/',
  terms: 'https://bizomat.ai/terms/',
  disclaimer: 'https://bizomat.ai/disclaimer/',
} as const;

/**
 * Where this app is served (same backend). The first is the primary address: under bizomat.ai/tasks (everything lives
 * under bizomat.ai, no subdomains); work.kevos.com is the old address, served at the root of its host.
 */
export const APP_HOSTS = ['bizomat.ai', 'work.kevos.com'] as const;

/** The platform links shown in the app shell and on the sign-in pages, in display order. */
export const PLATFORM_LINKS = {
  products: [
    { label: 'BIZOMAT', href: PLATFORM_URLS.website, title: 'The BIZOMAT platform website' },
    { label: 'CAD Automation', href: PLATFORM_URLS.cad, title: 'BIZOMAT CAD Automation' },
    { label: 'Resources', href: PLATFORM_URLS.resources, title: 'BIZOMAT Resources' },
  ],
  legal: [
    { label: 'Privacy', href: PLATFORM_URLS.privacy, title: 'BIZOMAT privacy policy' },
    { label: 'Terms', href: PLATFORM_URLS.terms, title: 'BIZOMAT terms' },
    { label: 'Disclaimer', href: PLATFORM_URLS.disclaimer, title: 'BIZOMAT disclaimer' },
  ],
} as const;

/** Anchor attributes for a platform link: same tab, and rel="noopener" when it leaves this app's host. */
export function platformLinkProps(href: string): { href: string; rel?: string } {
  let external = true;
  try {
    external = new URL(href, window.location.href).host !== window.location.host;
  } catch {
    /* keep external */
  }
  return external ? { href, rel: 'noopener' } : { href };
}

export function pageTitle(...parts: (string | null | undefined)[]) {
  return [...parts.filter(Boolean), BRAND.full].join(' · ');
}
